	/*
	 * Adding a new table_master
	 */
	function add()
	{
		$this->load->library('form_validation');

		$this->form_validation->set_rules('row', 'Row', 'required|numeric');
		$this->form_validation->set_rules('column', 'Column', 'required|numeric');

		if ($this->form_validation->run()) {

			$lableHeaders =explode(',', $this->input->post('lable_header'));

			foreach ($lableHeaders as $key => $header) {
				if ($header == "") {
					$lableHeaders[$key] = "-";
				}
			}
			$lableFooter = explode(',',$this->input->post('lable_footer'));
//			foreach ($lableFooter as $key => $header) {
//				if ($header == "") {
//					$lableFooter[$key] = "-";
//				}
//			}
			$lableRow = explode(',',$this->input->post('lable_row'));
			foreach ($lableRow as $key => $header) {
				if ($header == "") {
					$lableRow[$key] = "-";
				}
			}

			$params = array(
				'row' => $this->input->post('row'),
				'table_column' => $this->input->post('column'),
				'extra_label' => $this->input->post('extra_label'),
				'lable_header' => json_encode($lableHeaders),
				'lable_footer' => json_encode($lableFooter),
				'lable_row' => json_encode($lableRow),
				'created_by' => $this->user_data->id,
				'doctor_id' => $this->user_data->id,
				'status' => "Active",
				'created_at' => date('Y-m-d H:i:s'),
				'updated_at' => date('Y-m-d H:i:s'),
			);

			$table_master_id = $this->Table_master_model->add_table_master($params);
			redirect('doctor/table_master/index');
			$this->_alertSuccessResponce(true, "Table Inserted.", "Table not Inserted..", "doctor/table_master/index");

		} else {
			$this->view_data['_view'] = 'doctor/table_master/add';
			$this->load->view('layouts/master_page_doctors', $this->view_data);
		}
	}

