	 */
	function remove($id)
	{
		$table_master = $this->Table_master_model->get_table_master($id, $this->user_data->id);

		// check if the table_master exists before trying to delete it
		if (isset($table_master['id'])) {
			$this->Table_master_model->delete_table_master($id);
